export async function searchCities(query: string): Promise<City[]> {
  if (!query || query.length < 2) return [];
  try {
    const res = await fetch(
      `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(query)}&count=8&language=en&format=json`
    );
    const data = await res.json();
    if (!data.results) return [];
    return data.results.map((item: any) => ({
      name: item.name,
      lat: item.latitude,
      lon: item.longitude,
      state: item.admin1 || item.country,
      country: item.country,
    }));
  } catch (err) {
    return [];
  }
}

export async function getWeatherData(lat: number, lon: number) {
  const weatherRes = await fetch(
    `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,wind_speed_10m&hourly=temperature_2m&timezone=auto`
  );
  const weatherData = await weatherRes.json();

  const airRes = await fetch(
    `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${lat}&longitude=${lon}&hourly=pm2_5&timezone=auto`
  );
  const airData = await airRes.json();

  return {
    weather: weatherData,
    air: airData,
  };
}